def transform(grid):
    out = [row[:] for row in grid]
    for i, row in enumerate(grid):
        for j, value in enumerate(row):
            if value == 6:
                for di, color in [(-1, 8), (0, 3), (1, 0)]:
                    rr = i + di
                    if 0 <= rr < len(grid):
                        out[rr][j] = color
    return out
